surface:
struct NodeUniforms {
  viewProjection : mat4x4<f32>,
  model : mat4x4<f32>,
  params : vec4<f32>,
  u : array<vec4<f32>, 11>,
};

@group(0) @binding(0) var<uniform> node : NodeUniforms;

@group(1) @binding(0) var t_map : texture_2d<f32>;
@group(1) @binding(1) var s_map : sampler;

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) v_uv : vec2<f32>,
};

@vertex
fn vertexMain(
  @location(0) position : vec3<f32>,
  @location(3) normal : vec3<f32>,
  @location(2) uv : vec2<f32>,
) -> VertexOutput {
  var output : VertexOutput;
  output.v_uv = uv;
  let n2 : f32 = node.u[1].x;
  let n11 : f32 = node.params.y;
  let n12 : f32 = (n11 * n2);
  let n13 : f32 = sin(n12);
  let n18 : vec3<f32> = normal;
  let n19 : f32 = 0.25;
  let n20 : f32 = (n13 * n19);
  let n21 : vec3<f32> = (n18 * n20);
  let clip = node.viewProjection * node.model * vec4<f32>((position + n21), 1.0);
  // WebGL clip depth [-w, w] onto WebGPU's [0, w]; see wgpu-unlit.ts.
  output.position = vec4<f32>(clip.x, clip.y, (clip.z + clip.w) * 0.5, clip.w);
  return output;
}

@fragment
fn fragmentMain(input : VertexOutput) -> @location(0) vec4<f32> {
  let n0 : vec2<f32> = input.v_uv;
  let n1 : vec4<f32> = node.u[0];
  let n2 : f32 = node.u[1].x;
  let n3 : vec2<f32> = node.u[2].xy;
  let n4 : vec3<f32> = node.u[3].xyz;
  let n5 : mat3x3<f32> = mat3x3<f32>(node.u[4].xyz, node.u[5].xyz, node.u[6].xyz);
  let n6 : mat4x4<f32> = mat4x4<f32>(node.u[7], node.u[8], node.u[9], node.u[10]);
  let n7 : vec2<f32> = (n0 + n3);
  let n8 : vec4<f32> = textureSample(t_map, s_map, n7);
  let n9 : vec3<f32> = (n5 * n4);
  let n10 : vec4<f32> = (n6 * n1);
  let n11 : f32 = node.params.y;
  let n12 : f32 = (n11 * n2);
  let n13 : f32 = sin(n12);
  let n14 : vec4<f32> = (n8 * n10);
  let n15 : vec4<f32> = vec4<f32>(n9, n13);
  let n16 : vec4<f32> = (n14 + n15);
  let n17 : vec4<f32> = saturate(n16);
  let c = n17;
  return vec4<f32>(c.rgb, c.a * node.params.x);
}

screen:
@group(0) @binding(0) var t_source : texture_2d<f32>;
@group(0) @binding(1) var s_source : sampler;

struct NodeUniforms {
  params : vec4<f32>,
  u : array<vec4<f32>, 1>,
};

@group(1) @binding(0) var<uniform> node : NodeUniforms;

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) v_uv : vec2<f32>,
};

@vertex
fn vertexMain(@builtin(vertex_index) index : u32) -> VertexOutput {
  let corner = i32(index);
  let x = f32(corner / 2) * 4.0 - 1.0;
  let y = f32(corner & 1) * 4.0 - 1.0;
  var output : VertexOutput;
  output.position = vec4<f32>(x, y, 0.0, 1.0);
  output.v_uv = vec2<f32>((x + 1.0) * 0.5, (y + 1.0) * 0.5);
  return output;
}

@fragment
fn fragmentMain(input : VertexOutput) -> @location(0) vec4<f32> {
  let n0 : vec2<f32> = input.v_uv;
  let n1 : vec4<f32> = textureSample(t_source, s_source, vec2<f32>(n0.x, 1.0 - n0.y));
  let n2 : f32 = node.u[0].x;
  let n3 : vec3<f32> = n1.xyz;
  let n4 : vec3<f32> = (n3 * n2);
  let n5 : f32 = n1.w;
  let n6 : vec4<f32> = vec4<f32>(n4, n5);
  return n6;
}
